function CA_EVOLVE(state S, time t, prime p):
    op   <- { 1: 1 mod p, -1: 1 mod p }      # caOp = T + T^{-1}
    acc  <- { 0: 1 mod p }                    # identity polynomial
    base <- op
    e    <- t
    while e > 0:                              # binary exponentiation
        if e is odd:  acc <- POLY_MUL(acc, base, p)
        base <- POLY_MUL(base, base, p)
        e <- floor(e / 2)
    return POLY_MUL(S, acc, p)

function POLY_MUL(a, b, p):
    out <- empty map
    for (ea, ca) in a, (eb, cb) in b:
        out[ea+eb] <- (out[ea+eb] + ca*cb) mod p
    drop zero entries of out; return out

