function CA_OP_RENORM(prime p, level k):
    e <- p^k
    return { e: 1 mod p, -e: 1 mod p }        # T^{p^k} + T^{-p^k}

function CA_OP_RENORM_SEED(prime p, level k, site a):
    e <- p^k
    return { a+e: 1 mod p, a-e: 1 mod p }     # T^{a+p^k}+T^{a-p^k}

function LUCAS_LIVE_CELL_COUNT(time t, prime p):
    digits <- base-p representation of t (least significant first)
    product <- 1
    for d in digits:
        product <- product * (d + 1)
    return product            # = prod_i (d_i + 1)
